"""Parse bounded ss table text as data; unsupported formats are incomplete."""
import ipaddress

class Ambiguous(ValueError):
    pass

def table(text, side, selector):
    lines=text.splitlines()
    if not lines: raise Ambiguous('missing header')
    head=tuple(lines[0].split())
    # Header words determine a single explicit local column; no prefix or
    # reordered-column acceptance. A trailing Process column is recognized.
    columns=('State','Recv-Q','Send-Q','Local','Address:Port','Peer','Address:Port')
    supported={columns, columns+('Process',), ('Netid',)+columns, ('Netid',)+columns+('Process',)}
    # Exact native UDP layout observed in SS33 has no State column.
    udp_stateless=(side=='native' and selector=='udp' and head==
                   ('Recv-Q','Send-Q','Local','Address:Port','Peer','Address:Port'))
    if head not in supported and not udp_stateless: raise Ambiguous('unsupported or reordered header')
    netid=head[0]=='Netid'
    if side=='candidate' and not netid: raise Ambiguous('candidate header')
    if not netid and selector in ('unix','listen'): raise Ambiguous('ambiguous native family')
    local_column=2 if udp_stateless else 4 if netid else 3
    result=[]
    for line in lines[1:]:
        if not line.strip(): continue
        parts=line.split();offset=1 if netid else 0
        if len(parts)<(4 if udp_stateless else offset+5): raise Ambiguous('short row')
        family=parts[0] if netid else {'tcp':'tcp','udp':'udp'}.get(selector)
        if not family: raise Ambiguous('unknown family')
        result.append({'family':family,'state':None if udp_stateless else parts[offset], 'local':parts[local_column], 'peer':parts[local_column+1]})
    return result

def inet_endpoint(token):
    if token.startswith('['):
        pos=token.find(']')
        if pos<0 or token[pos+1:pos+2]!=':': raise Ambiguous('invalid bracketed endpoint')
        addr,port=token[1:pos],token[pos+2:]
    else:
        if ':' not in token: raise Ambiguous('missing port')
        addr,port=token.rsplit(':',1)
    if not port.isascii() or not port.isdecimal(): raise Ambiguous('non-numeric port')
    try: address=ipaddress.ip_address(addr)
    except ValueError as exc: raise Ambiguous('non-numeric address') from exc
    number=int(port)
    if not 0<=number<=65535: raise Ambiguous('port range')
    return str(address),number

def exact_witness(rows,selector,port,path,udp_peer=None,allow_udp_stateless=False):
    states={'tcp':{'ESTAB','ESTABLISHED'},'udp':{'ESTAB','ESTABLISHED'},'unix':{'ESTAB','ESTABLISHED','CONNECTED'},'listen':{'LISTEN','LISTENING'}}[selector]
    families={'tcp':{'tcp','tcp6'},'udp':{'udp','udp6'},'unix':{'u_str'},'listen':{'tcp','tcp6'}}[selector]
    matches=[]; ambiguous=False
    for row in rows:
        state_ok=row['state'] in states or (selector=='udp' and allow_udp_stateless and row['state'] is None)
        if row['family'] not in families or not state_ok: continue
        if selector=='unix':
            if row['local']==path: matches.append(row)
        else:
            try: address,n=inet_endpoint(row['local'])
            except Ambiguous: ambiguous=True;continue
            if address=='127.0.0.1' and n==port:
                if selector=='udp':
                    if not isinstance(udp_peer,list) or len(udp_peer)!=2:raise Ambiguous('UDP peer proof missing')
                    try: peer_address,peer_port=inet_endpoint(row['peer'])
                    except Ambiguous: ambiguous=True;continue
                    if [peer_address,peer_port]!=udp_peer:continue
                matches.append(row)
    if len(matches)>1: raise Ambiguous('multiple matching local endpoints')
    if not matches and ambiguous: raise Ambiguous('unparseable possible witness')
    return bool(matches)


def udp_proc_witness(snapshot):
    """Match owned UDP FD inode and connected local/peer tuple to procfs data."""
    import re
    try:
        local=snapshot['udp_local'];peer=snapshot['udp_peer'];sink=snapshot['udp_sink']
        if (not isinstance(local,list) or not isinstance(peer,list) or not isinstance(sink,list)
                or len(local)!=2 or len(peer)!=2 or peer!=sink
                or any(x[0]!='127.0.0.1' or type(x[1]) is not int or not 1<=x[1]<=65535 for x in (local,peer))
                or snapshot['udp_port']!=local[1]):raise Ambiguous('UDP tuple invalid')
        links=snapshot['fd_targets'];m=re.fullmatch(r'socket:\[(\d+)\]',links['udp'])
        sink_m=re.fullmatch(r'socket:\[(\d+)\]',links['udp_sink'])
        if not m or not sink_m or m.group(1)==sink_m.group(1):raise Ambiguous('UDP FD inode invalid')
        raw=snapshot['udp_proc_raw']
        if not isinstance(raw,str) or len(raw.encode())>524288:raise Ambiguous('UDP proc data cap')
        def endpoint(token):
            addr,port=token.split(':');
            if len(addr)!=8 or len(port)!=4:raise Ambiguous('UDP proc tuple format')
            return [str(ipaddress.IPv4Address(int(addr,16).to_bytes(4,'little'))),int(port,16)]
        rows=[];sink_rows=[]
        for line in raw.splitlines()[1:]:
            fields=line.split()
            if len(fields)<10:raise Ambiguous('UDP proc short row')
            if fields[9]==m.group(1):rows.append(fields)
            if fields[9]==sink_m.group(1):sink_rows.append(fields)
        if len(rows)!=1:raise Ambiguous('UDP inode missing or duplicated')
        row=rows[0]
        if endpoint(row[1])!=local or endpoint(row[2])!=peer or row[3]!='01' or row[7]!='2000':raise Ambiguous('UDP proc connected tuple/state/uid mismatch')
        if len(sink_rows)!=1 or endpoint(sink_rows[0][1])!=sink or sink_rows[0][3]!='07' or sink_rows[0][7]!='2000':raise Ambiguous('UDP peer socket proc identity mismatch')
        return {'inode':m.group(1),'sink_inode':sink_m.group(1),'local':local,'peer':peer,'proc_state':row[3]}
    except (KeyError,TypeError,ValueError,IndexError) as exc:
        if isinstance(exc,Ambiguous):raise
        raise Ambiguous('invalid UDP proc witness') from exc

