#!/usr/bin/python3
"""Guest data adjudication; process every surviving journal entry on cleanup."""
import base64,json,re
from pathlib import Path
from endpoint_parser import Ambiguous, table, exact_witness, udp_proc_witness

def output(rec,key='out'):return base64.b64decode(rec[key+'_base64'],validate=True).decode('utf-8','strict')
def analyse(before,after,calls,cleanup,read_errors):
 result={'controls':'incomplete','candidate':'INCOMPLETE','checks':{},'observations':[],'control_errors':list(read_errors)}
 expected=[(side,name,[flag]) for side in ('native','candidate') for name,flag in [('tcp','-t'),('udp','-u'),('unix','-x'),('listen','-l')]]
 identity_ok=False
 try:
  assert cleanup=={'incoming_status':0,'term_status':0,'wait_status':0,'forced':0}
  assert before['uid']==after['uid']==2000 and before['pid']==after['pid'] and before['netns']==after['netns'] and before['fd_targets']==after['fd_targets']
  assert before['proc_stat'].rsplit(')',1)[1].split()[19]==after['proc_stat'].rsplit(')',1)[1].split()[19]
  udp_before=udp_proc_witness(before);udp_after=udp_proc_witness(after)
  assert udp_before==udp_after
  result['udp_proc_witness']=udp_before
  assert len(calls)==8 and [(x['side'],x['selector'],x['argv']) for x in calls]==expected
  assert all(x['shell_netns']==before['netns'] and re.search(r'^Uid:\s+2000\s+2000',x['shell_status'],re.M) for x in calls)
  assert len({(x['shell_pid'],x['shell_stat'].rsplit(')',1)[1].split()[19]) for x in calls})==1
  identity_ok=not read_errors
 except Exception as exc:result['control_errors'].append('identity_journal_or_cleanup:'+type(exc).__name__)
 for index,rec in enumerate(calls):
  if rec.get('side')!='candidate' or rec.get('selector') not in ('tcp','udp','unix','listen'):continue
  name=rec['selector'];check={'journal_index':index,'selector_name':name,'raw_status':rec.get('status'),'selector':'INCOMPLETE','positive_witness':'INCOMPLETE'}
  result['observations'].append(check);result['checks'][name]=check
  # Preserve a reached nonzero status even if the output is empty or malformed;
  # attribution still requires controls and independently inspected raw bytes.
  if type(rec.get('status')) is int and rec['status']!=0:check['selector']='FAIL'
  try:
   if rec.get('truncated') is not False or rec.get('identity_error') is not None:raise ValueError('truncated or identity-incomplete call')
   rows=table(output(rec),'candidate',name);allowed={'tcp':{'tcp','tcp6'},'udp':{'udp','udp6'},'unix':{'u_str','u_dgr','u_seq'}}
   wrong_family=name!='listen' and any(row['family'] not in allowed[name] for row in rows)
   wrong_state=name=='listen' and any(row['state'] not in ('LISTEN','LISTENING','UNCONN') for row in rows)
   check['selector']='FAIL' if rec['status']!=0 or output(rec,'err') or wrong_family or wrong_state else 'PASS'
   port=before['udp_port'] if name=='udp' else before['tcp_port']
   check['positive_witness']='YES' if exact_witness(rows,name,port,before['unix_path'],udp_peer=before.get('udp_peer')) else 'NO'
  except (Ambiguous,KeyError,TypeError,ValueError,UnicodeError) as exc:check['error']=type(exc).__name__+': '+str(exc)
 native_ok=identity_ok
 for name in ('tcp','udp','unix','listen'):
  try:
   rec=next(x for x in calls if x.get('side')=='native' and x.get('selector')==name)
   if rec.get('truncated') is not False or rec.get('identity_error') is not None:raise ValueError('native truncated or identity-incomplete call')
   if rec['status']!=0 or output(rec,'err'):raise ValueError('native status or stderr')
   rows=table(output(rec),'native',name);port=before['udp_port'] if name=='udp' else before['tcp_port']
   if not exact_witness(rows,name,port,before['unix_path'],udp_peer=before.get('udp_peer'),allow_udp_stateless=(name=='udp')):raise ValueError('native witness missing')
  except Exception as exc:native_ok=False;result['control_errors'].append(name+':'+type(exc).__name__+': '+str(exc))
 if native_ok:
  result['controls']='complete';checks=result['checks']
  if set(checks)=={'tcp','udp','unix','listen'}:
   if any(c['selector']=='FAIL' for c in checks.values()):result['candidate']='FAIL'
   elif all(c['selector']=='PASS' and c['positive_witness']=='YES' for c in checks.values()):result['candidate']='PASS'
 return result

def main():
 h=Path('/tmp/parity-home');errors=[]
 def load(name):
  try:return json.loads((h/name).read_text())
  except Exception as exc:errors.append(name+':'+type(exc).__name__);return {}
 before=load('ss-holder-before.json');after=load('ss-holder-after.json');cleanup=load('ss-cleanup.json');calls=[]
 try:
  for line in (h/'ss-calls.jsonl').read_text().splitlines():
   try:calls.append(json.loads(line))
   except (ValueError,TypeError) as exc:errors.append('journal-line:'+type(exc).__name__);break
 except Exception as exc:errors.append('journal:'+type(exc).__name__)
 result=analyse(before,after,calls,cleanup,errors)
 (h/'ss-analysis.json').write_text(json.dumps(result,sort_keys=True,indent=2)+'\n')
 print('controls='+result['controls']+' candidate='+result['candidate'])
if __name__=='__main__':main()

