#!/usr/bin/python3
"""Guest-only validation of a held socket witness before selector calls."""
import json,os,re,sys
from pathlib import Path
from endpoint_parser import udp_proc_witness
if len(sys.argv)!=3:raise SystemExit(125)
pid=int(sys.argv[1]);shell=int(sys.argv[2]);d=json.loads(Path('/tmp/parity-home/ss-holder-before.json').read_text());p=Path('/proc')/str(pid)
if d['pid']!=pid or d['uid']!=2000 or not re.search(r'^Uid:\s+2000\s+2000', (p/'status').read_text(),re.M):raise ValueError('wrong owner')
if d['netns']!=os.readlink(str(p/'ns/net')) or d['netns']!=os.readlink('/proc/'+str(shell)+'/ns/net'):raise ValueError('wrong network namespace')
if d['proc_stat'].rsplit(')',1)[1].split()[19]!=(p/'stat').read_text().rsplit(')',1)[1].split()[19]:raise ValueError('wrong process birth')
if not d['fd_targets'] or any(not v.startswith('socket:[') for v in d['fd_targets'].values()):raise ValueError('invalid socket identity')
actual=set()
for f in (p/'fd').iterdir():
 try: actual.add(os.readlink(f))
 except FileNotFoundError: pass
if not set(d['fd_targets'].values()) <= actual:raise ValueError('socket fds no longer held')
if any(type(d[k]) is not int or not 1<=d[k]<=65535 for k in ('tcp_port','udp_port')):raise ValueError('invalid port')
if d['unix_path']!='/tmp/parity-case/owned-ss.sock':raise ValueError('invalid unix path')

# Require the live, owned connected UDP inode and its exact procfs tuple.
udp_proc_witness(d)

