#!/usr/bin/python3
"""Guest-only durable bounded capture, including incomplete call records."""
import base64,json,os,sys
from pathlib import Path
if len(sys.argv)!=6:raise SystemExit(125)
side,name,status,pid,flag=sys.argv[1:];h=Path('/tmp/parity-home')
if side not in ('candidate','native') or name not in ('tcp','udp','unix','listen') or not status.isdecimal() or not pid.isdecimal():raise SystemExit(125)
r={'side':side,'selector':name,'status':int(status),'shell_pid':int(pid),'argv':[flag],'truncated':False,'identity_error':None}
try:
 proc=Path('/proc')/pid
 for key,file in [('shell_stat','stat'),('shell_status','status')]:
  text=(proc/file).read_text()
  if len(text.encode())>8192:raise ValueError('identity length cap')
  r[key]=text
 r['shell_netns']=os.readlink(proc/'ns/net')
except (OSError,ValueError) as exc:r['identity_error']=type(exc).__name__+': '+str(exc)
for key in ('out','err'):
 try:
  with (h/('ss-'+side+'-'+name+'.'+key)).open('rb') as f:b=f.read(32769)
  if len(b)>32768:r['truncated']=True;b=b[:32768]
  r[key+'_base64']=base64.b64encode(b).decode('ascii')
 except OSError as exc:
  r['identity_error']=(r['identity_error'] or '')+' stream:'+type(exc).__name__
  r[key+'_base64']=''
p=h/'ss-calls.jsonl'
with p.open('a',encoding='utf-8') as f:f.write(json.dumps(r,sort_keys=True)+'\n');f.flush();os.fsync(f.fileno())
if r['truncated'] or r['identity_error']:raise SystemExit(125)

