#!/usr/bin/python3
"""Guest-only bounded owned socket inventory; no host execution."""
import json, os, signal, socket, stat, sys, time, uuid
from pathlib import Path
case=Path('/tmp/parity-case'); home=Path('/tmp/parity-home')
if os.getuid()!=2000 or os.geteuid()!=2000 or Path.cwd()!=case or os.environ.get('HOME')!=str(home): raise SystemExit(125)
if Path('/sys/class/dmi/id/sys_vendor').read_text().strip()!='QEMU': raise SystemExit(125)
uuid.UUID(Path('/etc/bashos-parity-vm').read_text().strip())
for d in (case,home):
 s=d.lstat()
 if not stat.S_ISDIR(s.st_mode) or s.st_uid!=2000 or d.is_symlink(): raise SystemExit(125)
def unnamed_port(socktype, protocol):
 for _ in range(128):
  sock=socket.socket(socket.AF_INET,socktype);sock.bind(('127.0.0.1',0));port=sock.getsockname()[1]
  try: socket.getservbyport(port,protocol)
  except OSError: return sock
  sock.close()
 raise RuntimeError('no numeric-only ephemeral service port')
tcp=unnamed_port(socket.SOCK_STREAM,'tcp');tcp.listen(2)
peer=socket.socket();peer.connect(tcp.getsockname());accepted,_=tcp.accept()
udp_sink=socket.socket(socket.AF_INET,socket.SOCK_DGRAM);udp_sink.bind(('127.0.0.1',0))
udp=unnamed_port(socket.SOCK_DGRAM,'udp');udp.connect(udp_sink.getsockname())
path=str(case/'owned-ss.sock');unix=socket.socket(socket.AF_UNIX,socket.SOCK_STREAM);unix.bind(path);unix.listen(2)
unix_client=socket.socket(socket.AF_UNIX,socket.SOCK_STREAM);unix_client.connect(path);unix_accepted,_=unix.accept()
sockets={'tcp_listen':tcp,'tcp_peer':peer,'tcp_accepted':accepted,'udp':udp,'udp_sink':udp_sink,'unix_listen':unix,'unix_client':unix_client,'unix_accepted':unix_accepted}
def snapshot():
 return {'uid':os.getuid(),'gid':os.getgid(),'pid':os.getpid(),'netns':os.readlink('/proc/self/ns/net'),'proc_stat':Path('/proc/self/stat').read_text(),'status':Path('/proc/self/status').read_text(),'tcp_port':tcp.getsockname()[1],'udp_port':udp.getsockname()[1],'udp_local':list(udp.getsockname()),'udp_peer':list(udp.getpeername()),'udp_sink':list(udp_sink.getsockname()),'udp_proc_raw':Path('/proc/net/udp').read_text(),'unix_path':path,'fd_targets':{name:os.readlink('/proc/self/fd/'+str(s.fileno())) for name,s in sockets.items()}}
def save(name):
 p=home/name; tmp=home/(name+'.tmp');tmp.write_text(json.dumps(snapshot(),sort_keys=True)+'\n');os.replace(tmp,p)
stop=False
def finish(_sig,_frame):
 global stop;stop=True
signal.signal(signal.SIGTERM,finish)
save('ss-holder-before.json')
while not stop:time.sleep(0.05)
save('ss-holder-after.json')
for s in sockets.values():s.close()
os.unlink(path)
